import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import BarraNavegacion from "./componentes/diseno/BarraNavegacion";

// Contexto de autenticación
import { AuthProvider, useAuth} from "";

// Páginas
import DatosDelSostenedor from "./paginas/Sostenedor/DatosDelSostenedor";
import EstructuraDeCurso from "./paginas/Establecimientos/EstructuraDeCurso";
import AlumnosDelCurso from "./paginas/alumnos/AlumnosDelCurso";
import Login from "./paginas/auth/login";

// --- Wrappers de protección ---
function ProtectedRoute({ children }) {
  const { isAuth, status } = useAuth();
  if (status !== "ready") return null; // aquí puedes renderizar un Spinner
  if (!isAuth) return <Navigate to="/login" replace />;
  return children;
}

function AdminRoute({ children }) {
  const { isAuth, status, hasRole } = useAuth();
  if (status !== "ready") return null;
  if (!isAuth) return <Navigate to="/login" replace />;
  if (!hasRole("admin")) return <Navigate to="/login" replace />; // o a /403 si prefieres
  return children;
}

export default function App() {
  return (
    <AuthProvider>
      <BrowserRouter>
        <BarraNavegacion />
        <main>
          <Routes>
            {/* Login público */}
            <Route path="/login" element={<Login />} />

            {/* Rutas SOLO ADMIN */}
            <Route
              path="/"
              element={
                <AdminRoute>
                  <DatosDelSostenedor />
                </AdminRoute>
              }
            />
            <Route
              path="/sostenedor"
              element={
                <AdminRoute>
                  <DatosDelSostenedor />
                </AdminRoute>
              }
            />
            {/* Cursos del establecimiento */}
            <Route
              path="/establecimientos/:id/estructura"
              element={
                <AdminRoute>
                  <EstructuraDeCurso />
                </AdminRoute>
              }
            />
            {/* Alumnos de un curso específico */}
            <Route
              path="/establecimientos/:id/cursos/:cursoId/alumnos"
              element={
                <AdminRoute>
                  <AlumnosDelCurso />
                </AdminRoute>
              }
            />

            {/* 404 / fallback */}
            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
      </BrowserRouter>
    </AuthProvider>
  );
}
